190	const BRAND = { blue: "#3b82f6", purple: "#8a70fb", bg: "#0a101f", card: "#111a30" };
191	
192	/**
193	 * Shared responsive email shell (inline styles for client compatibility).
194	 * Kept for the synchronous, code-rendered `emails.*` templates below and any
195	 * existing importers. DB-template sends use `wrapEmail` in `lib/email-render`.
196	 */
197	export function layout(title: string, body: string): string {
198	  // Delegate to the shared premium shell so every email is consistent.
199	  const heading = title
200	    ? `<h1 style="margin:0 0 16px;font-size:21px;font-weight:700;color:#ffffff;line-height:1.25;">${title}</h1>`
201	    : "";
202	  return wrapEmail(`${heading}<div>${body}</div>`);
203	}
204	
205	export function button(href: string, label: string): string {
206	  return emailButton(href, label);
207	}
208	
209	// ---- Transactional templates ----
210	//
211	// The full transactional catalog lives in `lib/email-templates.ts` (30+
212	// templates, all composed from the shared inline-styled components). It is
213	// re-exported here as `emails` so every existing call site — `import { emails }
214	// from "@/lib/mailer"` — keeps working unchanged. Each entry returns
215	// `{ template, subject, html }`; the six original signatures are preserved.
216	export type { BuiltEmail };
217	
218	// ===========================================================================
219	// Card billing & dunning templates
220	//
221	// Renewals apply wallet credit first, then auto-charge the customer's saved
222	// card for the remainder. When that charge fails we retry on day 1, 3 and 5 and
223	// only suspend once the retries are exhausted. These templates carry that flow.
224	//
225	// They live here rather than in `lib/email-templates.ts` only because this file
226	// is the one owned by the card-billing change; they are built with the same
227	// `build()` shape and the same shared components, so they render identically to
228	// the rest of the catalog.
229	// ===========================================================================
230	
231	/**
232	 * Number of automatic retries in the dunning sequence (day 1, day 3, day 5).
233	 * `paymentRetryFailed` uses it to tell the customer how many attempts are left,
234	 * so the worker's retry schedule and this copy must agree.
235	 */
236	export const DUNNING_RETRY_ATTEMPTS = 3;
237	
238	/**
239	 * Same composition helper as `lib/email-templates.ts` (which keeps its copy
240	 * module-private): eyebrow → heading → body blocks → single CTA → optional
241	 * footnote, wrapped with a preheader by the shared shell.
242	 */
243	function build(opts: {
244	  template: string;
245	  subject: string;
246	  preheader: string;
247	  eyebrow?: string;
248	  accent?: Accent;
249	  heading: string;
250	  blocks: string[];
251	  cta?: { href: string; label: string; accent?: Accent };
252	  note?: string;
253	}): BuiltEmail {
254	  const parts: string[] = [];
255	  if (opts.eyebrow) parts.push(emailEyebrow(opts.eyebrow, opts.accent ?? "violet"));
256	  parts.push(emailHeading(opts.heading));
257	  parts.push(...opts.blocks);
258	  if (opts.cta) parts.push(emailButton(opts.cta.href, opts.cta.label, opts.cta.accent ?? "violet"));
259	  if (opts.note) parts.push(emailNote(opts.note));
260	  return {
261	    template: opts.template,
262	    subject: opts.subject,
263	    html: wrapEmail(parts.join("\n"), { preheader: opts.preheader }),
264	  };
265	}
266	
267	/** Masked card display used wherever we echo the saved card back. */
268	const cardLabel = (last4: string) => `&bull;&bull;&bull;&bull;&nbsp;${last4}`;
269	
270	/** `MM/YYYY` from the raw Stripe expiry fields — never guessed, only formatted. */
271	const expiryLabel = (expMonth: number, expYear: number) => `${String(expMonth).padStart(2, "0")}/${expYear}`;
272	
273	/** Reassurance line reused across the dunning sequence. Nothing is suspended yet. */
274	const stillRunning = (hostname: string, extra = "") =>
275	  emailBanner(`<b>${hostname}</b> is still running. Nothing has been suspended.${extra ? ` ${extra}` : ""}`, "success");
276	
277	const legacyPaymentFailed = catalogEmails.paymentFailed;
278	type LegacyPaymentFailedArgs = Parameters<typeof legacyPaymentFailed>[0];
279	
280	/**
281	 * Card charge declined — FIRST failure of the dunning sequence.
282	 *
283	 * Overloaded so the original catalog shape (`{ amount, reason, updateUrl? }`,
284	 * still used by the admin template previewer) keeps working alongside the new
285	 * renewal-dunning shape.
286	 */
287	function paymentFailed(a: LegacyPaymentFailedArgs): BuiltEmail;
288	function paymentFailed(
289	  hostname: string,
290	  amountFormatted: string,
291	  last4: string,
292	  retryDateFormatted: string,
293	  billingUrl: string,
294	): BuiltEmail;
295	function paymentFailed(
296	  a: string | LegacyPaymentFailedArgs,
297	  amountFormatted?: string,
298	  last4?: string,
299	  retryDateFormatted?: string,
300	  billingUrl?: string,
301	): BuiltEmail {
302	  if (typeof a !== "string") return legacyPaymentFailed(a);
303	  const hostname = a;
304	  const amount = amountFormatted ?? "";
305	  const card = last4 ?? "";
306	  const retryDate = retryDateFormatted ?? "";
307	  const href = billingUrl ?? `${appUrl()}/dashboard/billing`;
308	  return build({
309	    template: "payment_failed",
310	    subject: `Card declined for ${hostname} — we'll retry ${retryDate}`,
311	    preheader: `${hostname} is still running. We'll try the card again on ${retryDate}.`,
312	    eyebrow: "Payment issue",
313	    accent: "warn",
314	    heading: "We couldn't charge your card",
315	    blocks: [
316	      emailParagraph(
317	        `The renewal payment for <b>${hostname}</b> didn't go through. Declines are usually something on the bank's side — a routine fraud check, a spending limit, or a card that's been reissued — so this often isn't anything you did.`,
318	      ),
319	      stillRunning(hostname),
320	      emailPanel(
321	        emailKeyValue([
322	          ["Server", hostname],
323	          ["Amount due", amount],
324	          ["Card", cardLabel(card)],
325	          ["Next attempt", retryDate],
326	        ]),
327	        "warn",
328	      ),
329	      emailParagraph(
330	        `We'll try the same card again on <b>${retryDate}</b>. If you'd rather not wait, update your card and we'll charge it straight away.`,
331	      ),
332	    ],
333	    cta: { href, label: "Update payment method", accent: "warn" },
334	    note: "If your bank asked you to approve the charge, approving it is enough. Anything else — just reply to this email and our team will take a look.",
335	  });
336	}
337	
338	const billingEmails = {
339	  /** Successful auto-charge against the saved card. */
340	  paymentReceipt: (amountFormatted: string, description: string, last4: string): BuiltEmail =>
341	    build({
342	      template: "payment_receipt",
343	      subject: `Receipt for ${amountFormatted} — card ending ${last4}`,
344	      preheader: `We charged ${amountFormatted} to your saved card. Everything is running as normal.`,
345	      eyebrow: "Receipt",
346	      accent: "success",
347	      heading: "Payment received",
348	      blocks: [
349	        emailParagraph(
350	          "Your renewal has been paid automatically using the card saved on your account. Everything is running as normal — there's nothing you need to do.",
351	        ),
352	        emailPanel(
353	          emailKeyValue([
354	            ["Amount", `<span style="color:#15a34a;">${amountFormatted}</span>`],
355	            ["For", description],
356	            ["Card", cardLabel(last4)],
357	          ]),
358	          "success",
359	        ),
360	        emailParagraph("Any wallet credit on your account was applied first; the amount above is what we charged to the card."),
361	      ],
362	      cta: { href: `${appUrl()}/dashboard/invoices`, label: "View invoices" },
363	      note: "Keep this email for your records, or download the itemised invoice from your dashboard at any time.",
364	    }),
365	
366	  /** First declined charge in the dunning sequence (see the overloads above). */
367	  paymentFailed,
368	
369	  /** A later retry in the dunning sequence was declined. */
370	  paymentRetryFailed: (
371	    hostname: string,
372	    amountFormatted: string,
373	    attempt: number,
374	    finalDateFormatted: string,
375	    billingUrl: string,
376	  ): BuiltEmail => {
377	    const remaining = Math.max(0, DUNNING_RETRY_ATTEMPTS - attempt);
378	    const remainingLine =
379	      remaining > 0
380	        ? `We'll try ${remaining} more time${remaining === 1 ? "" : "s"} before then.`
381	        : "That was the last automatic attempt.";
382	    return build({
383	      template: "payment_retry_failed",
384	      subject: `Payment retry ${attempt} declined for ${hostname} — still running until ${finalDateFormatted}`,
385	      preheader: `${hostname} stays online until ${finalDateFormatted}. ${remainingLine}`,
386	      eyebrow: `Retry ${attempt} declined`,
387	      accent: "warn",
388	      heading: "Your card was declined again",
389	      blocks: [
390	        emailParagraph(
391	          `We tried the saved card for <b>${hostname}</b> again and it was declined. If the card is fine on your end, it's worth asking your bank whether they're blocking the charge — that's the usual cause at this stage.`,
392	        ),
393	        stillRunning(hostname, `It stays online until <b>${finalDateFormatted}</b>.`),
394	        emailPanel(
395	          emailKeyValue([
396	            ["Server", hostname],
397	            ["Amount due", amountFormatted],
398	            ["Attempt", String(attempt)],
399	            ["Attempts remaining", String(remaining)],
400	            ["Suspends on", finalDateFormatted],
401	          ]),
402	          "warn",
403	        ),
404	        emailParagraph(
405	          `${remainingLine} If the balance is still unpaid on <b>${finalDateFormatted}</b>, <b>${hostname}</b> will be suspended — your data stays intact and paying restores it.`,
406	        ),
407	        emailParagraph("Updating your card now settles the balance immediately and stops the remaining retries."),
408	      ],
409	      cta: { href: billingUrl, label: "Update payment method", accent: "warn" },
410	      note: "If something about this charge looks wrong, or you need a little more time, reply to this email — we'd rather work it out with you.",
411	    });
412	  },
413	
414	  /** Stripe returned `requires_action` — the customer must complete 3-D Secure. */
415	  paymentActionRequired: (hostname: string, amountFormatted: string, authUrl: string): BuiltEmail =>
416	    build({
417	      template: "payment_action_required",
418	      subject: `Confirm the ${amountFormatted} payment for ${hostname} with your bank`,
419	      preheader: `${hostname} is still running. Your bank needs one quick confirmation to finish the payment.`,
420	      eyebrow: "Confirmation needed",
421	      accent: "info",
422	      heading: "Your bank needs to confirm this payment",
423	      blocks: [
424	        emailParagraph(
425	          `Your card issuer asked for an extra verification step before the renewal payment for <b>${hostname}</b> can complete. This is a routine security check on their side, and it takes less than a minute.`,
426	        ),
427	        stillRunning(hostname, "Confirming the payment keeps it that way."),
428	        emailPanel(
429	          emailKeyValue([
430	            ["Server", hostname],
431	            ["Amount", amountFormatted],
432	            ["Waiting on", "Bank confirmation (3-D Secure)"],
433	          ]),
434	        ),
435	        emailParagraph("Use the button below to confirm with your bank. We'll finish the payment as soon as they approve it."),
436	      ],
437	      cta: { href: authUrl, label: "Confirm payment with your bank" },
438	      note: `This confirmation link is unique to this payment and expires after a short while. If it's already expired, open <a href="${appUrl()}/dashboard/billing" style="color:#6f47f5;">Billing</a> and we'll start a fresh attempt.`,
439	    }),
440	
441	  /** Final retry failed — the last warning before the server is suspended. */
442	  paymentFinalNotice: (hostname: string, amountFormatted: string, billingUrl: string): BuiltEmail =>
443	    build({
444	      template: "payment_final_notice",
445	      subject: `Final notice for ${hostname} — ${amountFormatted} still unpaid`,
446	      preheader: `${hostname} is still running, but this is the last notice before it's suspended.`,
447	      eyebrow: "Final notice",
448	      accent: "danger",
449	      heading: "Last notice before suspension",
450	      blocks: [
451	        emailParagraph(
452	          `We've now tried the saved card for <b>${hostname}</b> as many times as we can, and it's still being declined. We've run out of automatic attempts, so this is the last message before the server has to be paused.`,
453	        ),
454	        stillRunning(hostname, `Paying the outstanding <b>${amountFormatted}</b> keeps it online.`),
455	        emailPanel(
456	          emailKeyValue([
457	            ["Server", hostname],
458	            ["Outstanding", amountFormatted],
459	            ["Status", "Running — awaiting payment"],
460	          ]),
461	          "danger",
462	        ),
463	        emailParagraph(
464	          "If the server is suspended it stops serving traffic, but nothing is deleted — your data and configuration stay exactly as they are, and settling the balance brings it straight back.",
465	        ),
466	        emailParagraph("Paying now, or switching to a different card, avoids the suspension entirely."),
467	      ],
468	      cta: { href: billingUrl, label: "Settle the balance", accent: "danger" },
469	      note: "If the charge looks wrong, or you need a few more days, reply to this email before the suspension date — we'd much rather sort it out with you than pause anything.",
470	    }),
471	
472	  /** Proactive heads-up that the card saved for auto-renewal is about to expire. */
473	  cardExpiringSoon: (last4: string, expMonth: number, expYear: number, billingUrl: string): BuiltEmail =>
474	    build({
475	      template: "card_expiring_soon",
476	      subject: `Your card ending ${last4} expires ${expiryLabel(expMonth, expYear)}`,
477	      preheader: "Nothing is wrong today — just a heads-up so your next renewal goes through.",
478	      eyebrow: "Card expiring",
479	      accent: "warn",
480	      heading: "Your saved card expires soon",
481	      blocks: [
482	        emailParagraph(
483	          `The card we use for automatic renewals expires on <b>${expiryLabel(expMonth, expYear)}</b>. Saving an up-to-date card now means your next renewal goes through without anyone having to think about it.`,
484	        ),
485	        emailBanner("All of your services are running normally. There's nothing wrong with your account today.", "success"),
