6	export async function POST(req: NextRequest) {
7	  const user = await currentUser();
8	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
9	  if (!stripeConfigured()) {
10	    return NextResponse.json({ error: "Stripe is not configured yet" }, { status: 400 });
11	  }
12	  const { amount } = await req.json().catch(() => ({}));
13	  const dollars = Number(amount);
14	  if (!Number.isFinite(dollars) || dollars > 5000) {
15	    return NextResponse.json({ error: "Amount must be $5–$5000" }, { status: 400 });
16	  }
17	  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
18	  const minTopup = await getSettingInt("min_topup_cents", 500);
19	  if (Math.round(dollars * 100) < minTopup) {
20	    return NextResponse.json(
21	      { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}` },
22	      { status: 400 },
23	    );
24	  }
25	  const base = process.env.APP_URL ?? "http://localhost:3000";
26	  const session = await stripe().checkout.sessions.create({
27	    mode: "payment",
28	    customer_email: user.email,
29	    line_items: [
30	      {
31	        price_data: {
32	          currency: "usd",
33	          product_data: { name: "Nxeon wallet credit" },
34	          unit_amount: Math.round(dollars * 100),
35	        },
36	        quantity: 1,
37	      },
38	    ],
39	    metadata: { nxeonUserId: user.id },
40	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
41	    cancel_url: `${base}/dashboard/billing?canceled=1`,
42	  });
43	  return NextResponse.json({ url: session.url });
44	}
