120	// ---------- Admin: coupon management ----------
121	
122	const couponSchema = z.object({
123	  code: z
124	    .string()
125	    .trim()
126	    .min(3)
127	    .max(32)
128	    .regex(/^[A-Za-z0-9_-]+$/, "Code: letters, digits, dashes/underscores only."),
129	  kind: z.enum(["PERCENT", "FIXED_CENTS", "CREDIT_CENTS"]),
130	  scope: z.enum(["ANY", "TOPUP", "ORDER"]),
131	  value: z.coerce.number().int().min(1).max(1_000_000),
132	  firstTimeOnly: z.coerce.boolean(),
133	  minAmountCents: z.coerce.number().int().min(0).max(10_000_000).optional(),
134	  maxRedemptions: z.coerce.number().int().min(1).max(1_000_000).optional(),
135	  expiresAt: z.string().optional(),
136	  note: z.string().max(200).optional(),
137	});
