200	  if (!coupon) return;
201	  await db.coupon.update({ where: { id }, data: { active: !coupon.active } });
202	  await db.auditLog.create({
203	    data: {
204	      userId: admin.id,
205	      action: "admin.coupon_toggle",
206	      detail: `${coupon.code} -> ${!coupon.active ? "active" : "inactive"}`,
207	    },
