1	// Single fulfilment path for a paid Stripe Checkout session, shared by BOTH the
2	// success-redirect route and the webhook. Plain server module (not "use server").
3	//
4	// WHY THIS EXISTS (2026-07-25)
5	// Fulfilment used to live in `app/api/stripe/confirm/route.ts` and was gated on
6	// whether `creditCheckoutSession()` returned true. That boolean is true only for
7	// the caller that won the race to insert the wallet credit — and the webhook
8	// calls the same function and discards the result. So:
9	//
10	//   * Race: the webhook's insert lands first, the confirm request gets P2002,
11	//     `credited === false`, and the redirect quietly lands on an empty page.
12	//     $249 charged, $249 credited, no server, no error, no notification.
13	//   * Deterministic: the customer closes the tab before `success_url` resolves,
14	//     so the confirm route never runs at all. Same outcome, 100% reproducible.
15	//
16	// Stripe's own guidance is explicit that a browser redirect must not be the
17	// fulfilment trigger. Now BOTH callers run this, and a `FulfilledSession` row —
18	// its own marker, not a side effect of crediting — decides the single winner.
19	
20	import { db } from "./db";
21	import {
22	  creditCheckoutSession,
23	  getCheckoutOrderIntent,
24	  getCheckoutResizeIntent,
25	  getCheckoutDiskExpandIntent,
26	} from "./stripe";
27	import { placeOrder } from "./order";
28	import { applyResize } from "./resize";
29	import { applyDiskExpand } from "./disk-expand";
30	
31	export type FulfilResult = {
32	  /** Where the browser should end up. The webhook ignores this. */
33	  redirect: string;
34	  /** True when THIS call performed the fulfilment work. */
35	  fulfilled: boolean;
36	  kind: "order" | "resize" | "diskExpand" | "topup" | "none";
37	  error?: string;
38	};
39	
40	/**
41	 * Claim exclusive responsibility for fulfilling `sessionId`.
42	 * Returns false when another caller already holds the claim — the UNIQUE index,
43	 * not a read-then-write check, is what makes this safe under concurrency.
44	 */
45	async function claim(sessionId: string, kind: string): Promise<boolean> {
46	  try {
47	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionId, kind } });
48	    return true;
49	  } catch (e) {
50	    if ((e as { code?: string })?.code === "P2002") return false; // someone else has it
51	    throw e;
52	  }
53	}
54	
55	async function settle(sessionId: string, status: "DONE" | "FAILED", detail?: string) {
56	  await db.fulfilledSession
57	    .update({ where: { stripeSessionId: sessionId }, data: { status, detail: detail?.slice(0, 500) } })
58	    .catch(() => {});
59	}
60	
61	/**
62	 * Credit the wallet and fulfil whatever the session was for, exactly once.
63	 * Safe to call repeatedly and concurrently from the redirect and the webhook.
64	 */
65	export async function fulfilCheckoutSession(sessionId: string, base = ""): Promise<FulfilResult> {
66	  // Crediting is separately idempotent (UNIQUE stripeSessionId on the wallet
67	  // transaction). We deliberately IGNORE its return value now — it reports who
68	  // won the credit race, which is not the same question as "has this been
69	  // fulfilled", and conflating the two was the bug.
70	  await creditCheckoutSession(sessionId).catch(() => false);
71	
72	  const order = await getCheckoutOrderIntent(sessionId);
73	  if (order) {
74	    if (!(await claim(sessionId, "order"))) {
75	      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "order" };
76	    }
77	    try {
78	      const user = await db.user.findUnique({ where: { id: order.userId } });
79	      if (!user) throw new Error("user not found for paid order");
80	      const serverId = await placeOrder(user, order.intent);
81	      await settle(sessionId, "DONE", serverId);
82	      return { redirect: `${base}/dashboard/servers/${serverId}`, fulfilled: true, kind: "order" };
83	    } catch (e) {
84	      // Payment is captured and the funds are in the wallet — record the failure
85	      // so it is reconcilable rather than invisible, and tell the customer.
86	      const msg = String((e as Error)?.message ?? e);
87	      await settle(sessionId, "FAILED", msg);
88	      await db.notification
89	        .create({
90	          data: {
91	            userId: order.userId,
92	            title: "Payment received — we couldn't finish setting up your server",
93	            body: "Your payment is safe and sitting in your wallet. Our team has been alerted; deploy again or contact support and we'll sort it out.",
94	            href: "/dashboard/billing",
95	          },
96	        })
97	        .catch(() => {});
98	      return { redirect: `${base}/dashboard/deploy?paid=1`, fulfilled: false, kind: "order", error: msg };
99	    }
100	  }
101	
102	  const resize = await getCheckoutResizeIntent(sessionId);
103	  if (resize) {
104	    const back = `${base}/dashboard/servers/${resize.serverId}`;
105	    if (!(await claim(sessionId, "resize"))) {
106	      return { redirect: back, fulfilled: false, kind: "resize" };
107	    }
108	    try {
109	      await applyResize({
110	        serverId: resize.serverId,
111	        planId: resize.planId,
112	        actorUserId: resize.userId,
113	        chargeCents: resize.chargeCents,
114	      });
115	      await settle(sessionId, "DONE", resize.serverId);
116	      return { redirect: back, fulfilled: true, kind: "resize" };
117	    } catch (e) {
118	      const msg = String((e as Error)?.message ?? e);
119	      await settle(sessionId, "FAILED", msg);
120	      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "resize", error: msg };
121	    }
122	  }
123	
124	  const expand = await getCheckoutDiskExpandIntent(sessionId);
125	  if (expand) {
126	    const back = `${base}/dashboard/servers/${expand.serverId}`;
127	    if (!(await claim(sessionId, "diskExpand"))) {
128	      return { redirect: `${back}?tab=resize`, fulfilled: false, kind: "diskExpand" };
129	    }
130	    try {
131	      await applyDiskExpand({
132	        serverId: expand.serverId,
133	        addGB: expand.addGB,
134	        actorUserId: expand.userId,
135	        chargeCents: expand.chargeCents,
136	      });
137	      await settle(sessionId, "DONE", expand.serverId);
138	      return { redirect: `${back}?tab=resize`, fulfilled: true, kind: "diskExpand" };
139	    } catch (e) {
140	      const msg = String((e as Error)?.message ?? e);
141	      await settle(sessionId, "FAILED", msg);
142	      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "diskExpand", error: msg };
143	    }
144	  }
145	
146	  // Plain wallet top-up: crediting above is the whole job.
147	  return { redirect: `${base}/dashboard/billing?paid=1`, fulfilled: true, kind: "topup" };
148	}
149

  }
}

/** For the confirm route: the resize intent attached to a paid session, if any. */
export async function getCheckoutResizeIntent(
  sessionId: string,
): Promise<{ userId: string; serverId: string; planId: string; chargeCents: number } | null> {
  if (!stripeConfigured()) return null;
  try {
    const session = await stripe().checkout.sessions.retrieve(sessionId);
    const userId = session.metadata?.nxeonUserId;
    const raw = session.metadata?.nxeonResize;
    if (!userId || !raw || session.payment_status !== "paid") return null;
    const parsed = JSON.parse(raw) as { serverId: string; planId: string; chargeCents: number };
    return { userId, serverId: parsed.serverId, planId: parsed.planId, chargeCents: parsed.chargeCents };
  } catch {
    return null;
  }
}

/** For the confirm route: the order intent attached to a paid session, if any. */
export async function getCheckoutOrderIntent(
  sessionId: string,
): Promise<{ userId: string; intent: OrderIntent } | null> {
  if (!stripeConfigured()) return null;
  try {
    const session = await stripe().checkout.sessions.retrieve(sessionId);
    const userId = session.metadata?.nxeonUserId;
    const raw = session.metadata?.nxeonOrder;
    if (!userId || !raw || session.payment_status !== "paid") return null;
    return { userId, intent: JSON.parse(raw) as OrderIntent };
  } catch {
    return null;
  }
}

/**
 * Credit a user's wallet for a completed Checkout session, idempotently.
 * Called from both the success-redirect confirm route (works without HTTPS)
 * and the webhook (belt-and-suspenders once HTTPS is available).
 * Returns true if a credit was applied this call.
 */
export async function creditCheckoutSession(sessionId: string): Promise<boolean> {
  const session = await stripe().checkout.sessions.retrieve(sessionId);
  const userId = session.metadata?.nxeonUserId;
  const cents = session.amount_total ?? 0;
  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;

  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
  // session id inside the description.
  const legacy = await db.walletTransaction.findFirst({
    where: { stripeSessionId: null, description: { contains: session.id } },
  });
  if (legacy) return false;

  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
  // read-then-write check. The confirm-redirect and the webhook can arrive
  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
  // only the database can safely decide the winner. P2002 == already credited.
  try {
    await db.$transaction([
      db.walletTransaction.create({
        data: {
          userId,
          amountCents: cents,
          description: `Stripe payment (${session.id})`,
          stripeSessionId: session.id,
        },
      }),
      db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
      db.notification.create({
        data: {
          userId,
          title: `Payment of $${(cents / 100).toFixed(2)} received`,
          href: "/dashboard/billing",
        },
      }),
      // PAID invoice for the top-up. Created in the SAME guarded transaction as
      // the wallet credit, so the UNIQUE(stripeSessionId) constraint that makes
      // the credit idempotent also prevents a duplicate invoice on replay.
      db.invoice.create({
        data: invoiceCreateData({
          userId,
          description: "Wallet top-up",
          status: "PAID",
          lineItems: [
            { description: "Wallet top-up", qty: 1, unitCents: cents, amountCents: cents },
          ],
        }),
      }),
    ]);
  } catch (e) {
    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
    throw e;
  }
  // A funded wallet is the referred user's first paid action — reward both sides.
  try {
    const { maybeRewardReferral } = await import("./actions-growth");
    await maybeRewardReferral(userId);
  } catch { /* best-effort */ }
  try {
    const u = await db.user.findUnique({ where: { id: userId } });
    if (u) {
      const { sendMail, emails } = await import("./mailer");
      const tpl = emails.receipt(`$${(cents / 100).toFixed(2)}`, "wallet top-up");
      await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html });
    }
  } catch { /* best-effort */ }
  return true;
}

  // a customer's balance on their behalf.
  await assertNotImpersonating();
  // Security: never mint free wallet balance in production. The demo gateway that
  // credits without a real payment is only ever acceptable in non-production, and
  // is refused outright when NODE_ENV === "production" regardless of Stripe.
  if (process.env.NODE_ENV === "production") {
    return { error: "Please add funds with a card via the secure checkout." };
  }
  // Once Stripe is configured, the demo gateway is hard-disabled — top-ups must
  // go through Checkout.
  const { stripeConfigured } = await import("./stripe");
  if (stripeConfigured()) {
    return { error: "Please add funds with a card via the secure checkout." };
  }
  // Throttle demo top-ups per user+IP to prevent rapid free-credit minting.
  const topupHdrs = await headers();
  const topupIp = (topupHdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
  const topupRl = checkRateLimit(`topup:${user.id}:${topupIp}`, { max: 10, windowMs: 60 * 60 * 1000 });
  if (!topupRl.ok) {
    return { error: `Too many top-up attempts. Try again in ${topupRl.retryAfterSec}s.` };
  }
  const amount = Number(formData.get("amount"));
  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
    return { error: "Amount must be between $1 and $1000." };
  }
  const cents = Math.round(amount * 100);
  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
  const minTopup = await getSettingInt("min_topup_cents", 500);
  if (cents < minTopup) {
    return { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}.` };
  }

  // Optional promo code: applied via the COUPON_COOKIE the billing CouponField
  // sets. applyCouponToTopup re-validates for this user against the real amount.
  const jar = await cookies();
  const couponCode = jar.get(COUPON_COOKIE)?.value?.trim();
  let bonusCents = 0;
  let couponId: string | null = null;
  let couponLabel = "";
  if (couponCode) {
    const result = await applyCouponToTopup(couponCode, cents);
    if (result.ok) {
      bonusCents = result.bonusCents;
      couponId = result.couponId;
      couponLabel = result.label;
    }
  }

  await db.$transaction([
    db.user.update({
      where: { id: user.id },
      data: { balanceCents: { increment: cents + bonusCents } },
    }),
    db.walletTransaction.create({
      data: { userId: user.id, amountCents: cents, description: "Wallet top-up (demo gateway)" },
    }),
    ...(bonusCents > 0 && couponId
      ? [
          db.walletTransaction.create({
            data: {
              userId: user.id,
              amountCents: bonusCents,
              description: `Promo ${couponCode!.toUpperCase()} — ${couponLabel}`,
            },
          }),
          db.couponRedemption.create({
            data: { couponId, userId: user.id, amountCents: bonusCents, context: "topup" },
          }),
          db.coupon.update({
            where: { id: couponId },
            data: { timesRedeemed: { increment: 1 } },
          }),
        ]
      : []),
  ]);
  jar.delete(COUPON_COOKIE);
