/**
 * Send a campaign to every newsletter subscriber.
 *
 * Best-effort: marks the campaign SENDING, then walks the subscriber list one
 * message at a time via `sendMail` (which never throws and logs each attempt to
 * EmailLog). A failure to any single address is counted and skipped — it never
 * aborts the batch. A tiny per-message delay throttles the SMTP relay. On
 * completion the campaign is set SENT with the success count (or FAILED if not
 * a single message went out).
 */
export async function sendCampaign(id: string): Promise<{ error?: string; sent?: number }> {
  await requireArea("platform");

  const campaign = await db.newsletterCampaign.findUnique({ where: { id } });
  if (!campaign) return { error: "Campaign not found." };
  if (campaign.status === "SENDING") return { error: "This campaign is already being sent." };
  if (campaign.status === "SENT") return { error: "This campaign has already been sent." };

  const subscribers = await db.newsletterSubscriber.findMany({ select: { email: true } });
  if (subscribers.length === 0) return { error: "There are no subscribers to send to yet." };

  await db.newsletterCampaign.update({ where: { id }, data: { status: "SENDING" } });

