"use server";

import { z } from "zod";
import { Prisma } from "@prisma/client";
import { db } from "./db";

export type SubscribeResult = {
  ok: boolean;
  status: "subscribed" | "already" | "error";
  message: string;
};

const emailSchema = z.email();

/**
 * Add an email to the newsletter list. Idempotent: a repeat submission of the
 * same (case-insensitive) address is reported as "already" rather than an error,
 * and the unique constraint is the source of truth against races. No external
 * ESP — we just persist the lead for later export.
 */
export async function subscribe(
  email: string,
  source = "landing",
): Promise<SubscribeResult> {
  const raw = typeof email === "string" ? email.trim().toLowerCase() : "";

  if (!raw) {
    return { ok: false, status: "error", message: "Please enter your email address." };
  }
  if (raw.length > 200) {
    return { ok: false, status: "error", message: "That email address is too long." };
  }

  const parsed = emailSchema.safeParse(raw);
  if (!parsed.success) {
    return { ok: false, status: "error", message: "That doesn’t look like a valid email." };
  }
  const value = parsed.data;

  const cleanSource = (typeof source === "string" ? source.trim() : "").slice(0, 60) || "landing";

  const existing = await db.newsletterSubscriber.findUnique({ where: { email: value } });
  if (existing) {
    return {
      ok: true,
      status: "already",
      message: "You’re already on the list — thanks for sticking around!",
    };
  }

  try {
    await db.newsletterSubscriber.create({ data: { email: value, source: cleanSource } });
  } catch (err) {
    // Unique-constraint race: another request inserted the same email first.
    if (err instanceof Prisma.PrismaClientKnownRequestError && err.code === "P2002") {
      return {
        ok: true,
        status: "already",
        message: "You’re already on the list — thanks for sticking around!",
      };
    }
    return {
      ok: false,
      status: "error",
      message: "Something went wrong. Please try again in a moment.",
    };
  }

  return {
    ok: true,
    status: "subscribed",
    message: "You’re in! We’ll send occasional product news — no spam.",
  };
}

