/**
 * Notification preferences: the stored shape, the pure helpers — and the POLICY
 * that decides which messages those preferences are allowed to suppress.
 *
 * Plain module (safe to import from server components; client components must
 * import TYPES ONLY — the `mayDeliverTo` helper below reaches for `./db`). The
 * `"use server"` action file may only export async functions, so all of this
 * lives here.
 *
 * WHY THIS FILE GREW A POLICY (2026-07-26)
 * ---------------------------------------------------------------------------
 * `User.notificationPrefs` was written by the settings form and read by NOTHING
 * (QA-PRELAUNCH P1-32). A customer who unticked "Account email" still received
 * every receipt; the "Security alerts" toggle governed a channel that was never
 * built. That is the same defect this codebase keeps shipping: a control that
 * reports success and is read by nothing — the auto-suspend kill switch an
 * operator turned off before watching customer VMs get suspended anyway
 * (P1-5), and the domain-markup panel that displayed 0% while charging 25%
 * (P1-9).
 *
 * The dangerous half of fixing it is OVER-fixing it. If a preference could
 * suppress a declined payment, an imminent suspension, a security/2FA change or
 * a data-loss warning, then an unticked checkbox would silently swallow the one
 * message the customer had to see — and they would lose a server, or an
 * account, with no warning at all. That is strictly worse than the original bug.
 *
 * So suppressibility is decided by a message's TIER, declared once in the
 * catalogue below, and never by the call site. A send site cannot make itself
 * suppressible by passing the wrong flag, and an unrecognised kind resolves to
 * CRITICAL — if we guess wrong, we guess towards "delivered".
 */

export type NotificationPrefs = {
  /**
   * Non-urgent transactional EMAIL: payment receipts, activity notices.
   * Never covers the dunning sequence, suspensions or security changes.
   */
  email: boolean;
  /**
   * Product news / marketing. Unticking this also removes the address from the
   * campaign list (see `updateNotificationPrefs`) — the stored flag alone would
   * suppress nothing, because campaigns are addressed by email, not by user.
   */
  product: boolean;
  /**
   * Legacy key, pinned `true`.
   *
   * It used to render as a "Security alerts" toggle, which was dishonest twice
   * over: the channel it claimed to govern was never built (sign-in / token /
   * 2FA paths write audit rows only), and security, password and 2FA messages
   * must not be suppressible in the first place. Kept in the shape so
   * previously-stored values and the GDPR export keep round-tripping, and typed
   * as the literal `true` so no code path can ever write it back as
   * consent-withdrawn.
   */
  security: true;
};

export const DEFAULT_PREFS: NotificationPrefs = { email: true, product: true, security: true };

/**
 * Normalise whatever is stored in the Json column into a typed prefs object.
 * A missing or malformed key falls back to the default (opted IN) — the column
 * is nullable and predates this policy, so "absent" must never read as "the
 * customer opted out of everything".
 */
export function normalizePrefs(raw: unknown): NotificationPrefs {
  const p = (raw ?? {}) as Record<string, unknown>;
  return {
    email: typeof p.email === "boolean" ? p.email : DEFAULT_PREFS.email,
    product: typeof p.product === "boolean" ? p.product : DEFAULT_PREFS.product,
    security: true,
  };
}

/* -------------------------------------------------------------------------- */
/*                          Delivery policy                                   */
/* -------------------------------------------------------------------------- */

/** How a message reaches the customer. */
export type NotifyChannel = "email" | "inapp";

/**
 * Suppressibility tier.
 *
 * CRITICAL — "you need to know this". Delivered on every channel, always,
 *            whatever the preferences say. Money that failed to move, a service
 *            about to be suspended or deleted, a change to how the account is
 *            secured, or anything that can cost the customer data.
 * ACCOUNT  — informational transactional. Email is suppressible via
 *            `prefs.email`; the in-app bell is kept (see `isSuppressible`).
 * PRODUCT  — marketing. Suppressible on every channel via `prefs.product`.
 */
export type NotifyTier = "CRITICAL" | "ACCOUNT" | "PRODUCT";

/**
 * Every message kind the platform can send, and the ONE thing that decides
 * whether a preference may hold it back. Grouped by tier so the split is
 * reviewable at a glance — adding a kind is a deliberate act, and putting
 * something in ACCOUNT is a statement that a customer missing it entirely costs
 * them nothing they cannot recover.
 */
export const NOTIFY_KINDS = {
  // ---- CRITICAL: never suppressible, on any channel, by any preference. -----
  /** Password-reset link. The only way back into a locked-out account. */
  password_reset: "CRITICAL",
  /** Password changed, 2FA enabled/disabled, backup codes reissued, API token created/revoked. */
  security_change: "CRITICAL",
  /** Card declined, dunning retry declined, final notice. Money did not move. */
  payment_failed: "CRITICAL",
  /** 3-D Secure / `requires_action` — the payment stalls until the customer acts. */
  payment_action_required: "CRITICAL",
  /** Saved card expires soon: the next renewal will fail if it is not replaced. */
  card_expiring: "CRITICAL",
  /** Term is about to lapse. Suppressing this is how a paid-up customer loses a VM. */
  expiry_warning: "CRITICAL",
  /** Service suspended, or about to be. */
  suspension: "CRITICAL",
  /** Service terminated, or about to be — data destruction is imminent/done. */
  termination: "CRITICAL",
  /** Abuse / acceptable-use action against the account. */
  abuse: "CRITICAL",
  /** Anything that lost, or may lose, customer data (failed backup, restore, volume). */
  data_loss: "CRITICAL",
  /** Paid but not provisioned — the customer's money is in limbo. */
  fulfilment_failed: "CRITICAL",
  /** Refund or write-off issued against the account. */
  refund: "CRITICAL",

  // ---- ACCOUNT: informational transactional. Email opt-out honoured. -------
  welcome: "ACCOUNT",
  /** Receipt for a payment that SUCCEEDED. (A failure is `payment_failed`.) */
  receipt: "ACCOUNT",
  invoice: "ACCOUNT",
  /** Deploy / reinstall / migration finished successfully. */
  provision_done: "ACCOUNT",
  /** Backup taken, app installed, certificate issued, volume attached, … */
  job_done: "ACCOUNT",
  /** Domain registered / renewed / transferred. */
  domain_activity: "ACCOUNT",
  support_reply: "ACCOUNT",
  referral_bonus: "ACCOUNT",

  // ---- PRODUCT: marketing. Suppressible everywhere. ------------------------
  product_news: "PRODUCT",
} as const satisfies Record<string, NotifyTier>;

export type NotifyKind = keyof typeof NOTIFY_KINDS;

/**
 * Tier of a message kind. An unregistered kind resolves to CRITICAL on purpose:
 * the failure mode of a mis-typed or forgotten kind must be "delivered anyway",
 * never "silently dropped".
 */
export function notifyTier(kind: NotifyKind): NotifyTier {
  return (NOTIFY_KINDS as Record<string, NotifyTier>)[kind] ?? "CRITICAL";
}

/**
 * Does this (kind, channel) pair depend on the customer's preferences at all?
 *
 * `false` means the answer is unconditionally "deliver", so callers can skip the
 * preference lookup entirely — the gate costs nothing on the critical paths.
 */
export function isSuppressible(kind: NotifyKind, channel: NotifyChannel): boolean {
  const tier = notifyTier(kind);
  if (tier === "CRITICAL") return false;
  if (tier === "ACCOUNT") {
    // Email only. The in-app bell is the durable record inside the portal, and
    // the toggle the customer ticked says "email" — hiding an activity notice
    // from the portal would recreate the very failure this policy exists to
    // cure (information that quietly went missing), while suppressing the mail
    // is exactly what was asked for.
    return channel === "email";
  }
  return true; // PRODUCT — marketing has no business on a channel they declined.
}

/** Decide delivery from already-loaded preferences. */
export function mayDeliver(
  prefs: NotificationPrefs,
  kind: NotifyKind,
  channel: NotifyChannel,
): boolean {
  if (!isSuppressible(kind, channel)) return true;
  return notifyTier(kind) === "PRODUCT" ? prefs.product : prefs.email;
}

/**
 * Decide delivery for a user id, loading their preferences only when the answer
 * actually depends on them.
 *
 * Fails OPEN. A missing user row or a database hiccup returns `true`: a message
 * must never be dropped because a preference lookup failed — that would be a
 * silent swallow with no preference behind it at all.
 *
 * `./db` is imported lazily so this module stays statically safe to import from
 * anywhere (the settings page imports `normalizePrefs`, the client component
 * imports the type only).
 */
export async function mayDeliverTo(
  userId: string,
  kind: NotifyKind,
  channel: NotifyChannel,
): Promise<boolean> {
  if (!isSuppressible(kind, channel)) return true;
  try {
    const { db } = await import("./db");
    const row = await db.user.findUnique({
      where: { id: userId },
      select: { notificationPrefs: true },
    });
    if (!row) return true;
    return mayDeliver(normalizePrefs(row.notificationPrefs), kind, channel);
  } catch {
    return true;
  }
}

"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import type { NotificationPrefs } from "./prefs";

/**
 * Save notification preferences from the settings form.
 *
 * Ownership: `requireUser()` and the write is keyed on that user's own id — this
 * action takes no user id from the client, so it can only ever edit the caller.
 */
export async function updateNotificationPrefs(
  prev: unknown,
  formData: FormData,
): Promise<{ ok?: boolean; error?: string; note?: string }> {
  const user = await requireUser();
  const prefs: NotificationPrefs = {
    email: formData.get("email") === "on",
    product: formData.get("product") === "on",
    // Pinned true — see `NotificationPrefs.security`. Security, password and 2FA
    // messages are CRITICAL and must never be suppressible, so there is no
    // toggle for them and nothing may store a withdrawal of consent for them.
    security: true,
  };
  await db.user.update({ where: { id: user.id }, data: { notificationPrefs: prefs } });

  // Make "Product updates" real TODAY, not once someone else wires it.
  //
  // Campaigns are addressed from `NewsletterSubscriber` BY EMAIL ADDRESS
  // (lib/actions-newsletter-campaign.ts) — a table with no relation to `User` —
  // so storing `product: false` on the user suppresses precisely nothing. That
  // was the P1-32 failure at its worst: the customer withdraws marketing consent,
  // sees "Saved ✓", and the next campaign still lands in their inbox. For a
  // UK/EU customer that is a consent obligation, not a UX nicety.
  //
  // Deliberately one-way: turning the toggle ON does NOT subscribe them. This
  // form posts every checkbox on every save and `product` defaults to ticked, so
  // auto-subscribing would add customers to a marketing list as a side effect of
  // saving an unrelated preference. A toggle may withdraw consent; it must never
  // manufacture it.
  let note: string | undefined;
  if (!prefs.product) {
    const removed = await db.newsletterSubscriber.deleteMany({
      where: { email: user.email.toLowerCase() },
    });
    if (removed.count > 0) note = "Removed from the product-news list.";
  }

  revalidatePath("/dashboard/settings");
  return { ok: true, note };
}

"use client";

import { useActionState } from "react";
import { updateNotificationPrefs } from "@/lib/actions-prefs";
import type { NotificationPrefs } from "@/lib/prefs";

/**
 * Only the preferences that are actually honoured get a switch.
 *
 * The third row used to be "Security alerts — new sign-ins and changes to tokens
 * or 2FA". It was removed rather than relabelled: the channel it claimed to
 * govern was never built, AND security messages must not be suppressible at all
 * (see `lib/prefs.ts`). An honest statement beats a switch that promises a
 * guarantee nothing enforces — the same reasoning that keeps `AutoRecharge`
 * unrendered instead of shipped-but-unwired.
 *
 * `note` is the truthful current scope of each switch, not the scope we intend it
 * to have. "Product updates" removes the address from the campaign list the
 * moment it is saved; the receipt send site is still ungated, so we say so.
 */
const ROWS: { key: "email" | "product"; label: string; note: string }[] = [
  {
    key: "email",
    label: "Account email",
    note: "Non-urgent account email — activity notices and summaries. Payment receipts are still always sent today.",
  },
  {
    key: "product",
    label: "Product updates",
    note: "News, new features and occasional announcements. Turning this off takes you off the mailing list straight away.",
  },
];

export function NotificationPrefs({ prefs }: { prefs: NotificationPrefs }) {
  const [state, action, pending] = useActionState(updateNotificationPrefs, {});
  return (
    <form action={action} className="space-y-4">
      <ul className="divide-y divide-white/[0.05] rounded-xl border border-white/[0.06]">
        {ROWS.map((row) => (
          <li key={row.key} className="flex items-center justify-between gap-4 px-4 py-3">
            <div className="min-w-0">
              <p className="text-sm font-medium">{row.label}</p>
              <p className="text-xs text-slate-500">{row.note}</p>
            </div>
            <label className="relative inline-flex shrink-0 cursor-pointer items-center">
              <input
                type="checkbox"
                name={row.key}
                defaultChecked={prefs[row.key]}
                className="peer sr-only"
              />
              <span className="h-6 w-11 rounded-full bg-white/10 transition peer-checked:bg-brand-500 after:absolute after:left-0.5 after:top-0.5 after:h-5 after:w-5 after:rounded-full after:bg-white after:transition peer-checked:after:translate-x-5" />
            </label>
          </li>
        ))}
      </ul>

      {/* The messages no preference can hold back. Stated plainly so nobody
          expects the switches above to silence a suspension warning. */}
      <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
        <p className="text-sm font-medium">Always sent</p>
        <p className="mt-1 text-xs text-slate-500">
          Declined payments, expiry and suspension warnings, terminations, refunds, password resets
          and anything that could cost you data are delivered whatever you choose above — these can
          never be switched off. Sign-ins and changes to 2FA or API tokens are recorded in your
          account activity; we don&apos;t email those yet.
        </p>
      </div>

      <div className="flex items-center gap-3">
        <button className="btn-primary" disabled={pending}>
          {pending ? "Saving…" : "Save preferences"}
        </button>
        {state?.ok && (
          <span className="text-sm text-emerald-400">
            Saved ✓{state.note ? ` — ${state.note}` : ""}
          </span>
        )}
        {state?.error && <span className="text-sm text-red-400">{state.error}</span>}
      </div>
    </form>
  );
}

