// ---------- Coupons ----------

/**
 * Compute the extra wallet credit a coupon grants for a top-up of `baseCents`.
 * PERCENT -> baseCents * value%; CREDIT_CENTS -> flat `value` cents.
 *
 * FIXED_CENTS returns 0 and is refused before it ever reaches here — see the
 * guard in `applyCouponToTopup`. It used to return `coupon.value` as a *bonus*,
 * which turned a coupon the admin UI advertises as "$5.00 off" into $5.00 of free
 * balance. Kept at 0 so that if the guard is ever removed the failure mode is "no
 * bonus", not "mints money".
 */
function couponBonusForTopup(coupon: Coupon, baseCents: number): number {
  switch (coupon.kind) {
    case "PERCENT":
      return Math.round((baseCents * coupon.value) / 100);
    case "CREDIT_CENTS":
      return coupon.value;
    default:
      return 0;
  }
}

/**
 * Is a top-up promo code redeemable AT ALL right now?
 *
 * This mirrors, deliberately, the two guards at the top of `topUp`
 * (lib/actions.ts): the demo gateway is the ONLY code path in the product that
 * reads the `nxeon_coupon` cookie and grants the bonus, and it refuses when
 * NODE_ENV is production or when Stripe is configured. The real card path
 * (app/api/stripe/checkout/route.ts -> `creditCheckoutSession`) credits
 * `session.amount_total` verbatim, so it cannot add a bonus on top of what was
 * charged — no amount of work in this file changes that.
 *
 * So when this returns false a promo code cannot be honoured by anything, and
 * accepting one would reproduce the exact defect this codebase keeps shipping: a
 * green "Code applied" that is read by nothing (compare the auto-suspend kill
 * switch, and the domain markup that displayed 0% while charging 25%).
 *
 * TO TURN COUPONS BACK ON, one change is needed, in a file this change does not
 * own: `lib/fulfil-checkout.ts` must grant the bonus for a paid session inside
 * the same claim that stamps the `FulfilledSession` marker (details in the
 * handover notes for that file). Once the bonus is granted there, replace the
 * body of this function with `return true`.
 */
async function topupCouponRedeemable(): Promise<boolean> {
  const { stripeConfigured } = await import("./stripe");
  return process.env.NODE_ENV !== "production" && !stripeConfigured();
}

/**
 * Validate a promo code for the CURRENT user against a top-up of `baseCents` and
 * return the bonus that would be credited. Read-only: it never mutates state,
 * so it is safe to call both for the live preview (CouponField) and again inside
 * `topUp` to compute the real bonus. Enforces active / expiry / scope /
 * minAmount / maxRedemptions / firstTimeOnly / one-per-user rules.
 */
export async function applyCouponToTopup(
  code: string,
  baseCents: number
): Promise<CouponApplyResult> {
  const user = await requireUser();
  // Global kill-switch: when coupons are disabled no code may be redeemed.
  // Checked here so both the live preview and the real `topUp` apply are covered.
  if (!(await getSettingBool("coupons_enabled", true))) {
    return { ok: false, error: "Promo codes are currently disabled." };
  }
  // Honesty gate. Refuse BEFORE looking the code up, so we neither promise a
  // bonus no code path can grant nor leak which codes exist. See
  // `topupCouponRedeemable` for the single change that lifts this.
  if (!(await topupCouponRedeemable())) {
    return {
      ok: false,
      error:
        "Promo codes can’t be applied to card payments yet, so this code has not been applied — nothing has been charged. Contact support if you were given this code.",
    };
  }

  }
  const normalized = String(code ?? "").trim().toUpperCase();
  if (!normalized) return { ok: false, error: "Enter a promo code." };

  const coupon = await db.coupon.findUnique({ where: { code: normalized } });
  if (!coupon || !coupon.active) return { ok: false, error: "That code isn’t valid." };
  if (coupon.scope === "ORDER") {
    return { ok: false, error: "This code only applies to server orders." };
  }
  // "Fixed cents off" is a DISCOUNT, and a wallet top-up has nothing to discount:
  // the customer names the amount and pays exactly that. This kind used to be
  // handed to `couponBonusForTopup` and paid out as a bonus, so a coupon that
  // /admin/coupons renders as "$5.00 off" credited the customer $5.00 of free
  // balance instead (QA-PRELAUNCH P1-7). Refuse it rather than silently
  // reinterpret an admin's intent as its opposite.
  if (coupon.kind === "FIXED_CENTS") {
    return {
      ok: false,
      error: "This code is money off an order, not top-up credit — it can’t be used here.",
    };
  }
  if (coupon.expiresAt && coupon.expiresAt.getTime() < Date.now()) {
    return { ok: false, error: "This code has expired." };
  }
  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
    return { ok: false, error: "This code has reached its redemption limit." };
  }
  if (coupon.minAmountCents !== null && baseCents < coupon.minAmountCents) {
    return {
      ok: false,
      error: `Add at least $${(coupon.minAmountCents / 100).toFixed(2)} to use this code.`,
    };
  }

  // One redemption per user (mirrors the @@unique([couponId,userId]) constraint).
  const already = await db.couponRedemption.findUnique({
    where: { couponId_userId: { couponId: coupon.id, userId: user.id } },
  });
  if (already) return { ok: false, error: "You’ve already used this code." };

  if (coupon.firstTimeOnly) {
    // "First-time" = the user has never received a positive wallet credit before.
    const priorCredits = await db.walletTransaction.count({
      where: { userId: user.id, amountCents: { gt: 0 } },
    });
    if (priorCredits > 0) {
      return { ok: false, error: "This code is for first-time customers only." };
    }
  }

  const bonusCents = Math.max(0, couponBonusForTopup(coupon, baseCents));
  return {
    ok: true,
    couponId: coupon.id,
    code: coupon.code,
    bonusCents,
    label: describeCoupon(coupon),
  };
}

